    question: "<small class='instruction-note'>日本文に合うように、次の語句を並び替えなさい。</small><br>I ( &nbsp; &nbsp; &nbsp; )( &nbsp; &nbsp; &nbsp; )( &nbsp; &nbsp; &nbsp; )( &nbsp; &nbsp; &nbsp; ) at the barber's.<br><small>私は床屋さんで髪を刈ってもらいました。</small>",
